contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Attempt to withdraw 'amt' from c; caller must fund this test if needed for other operations.
    function run(uint256 amt) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        // no precondition on amt; we observe behavior for any input
        // record balances before the call
        uint256 beforeC = address(c).balance;
        uint256 beforeThis = address(this).balance;

        bool reverted;
        // call withdraw on c as this contract
        c.withdraw(amt); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterC = address(c).balance;
        uint256 afterThis = address(this).balance;

        // General rule:
        // - If the call reverted, neither observable balance changed.
        // - If the call succeeded, contract balance decreased by exactly amt, and this contract's observable balance increased by at most amt (no Ether created).
        assert(
            (reverted && afterC == beforeC && afterThis == beforeThis)
            || (!reverted && afterC + amt == beforeC && afterThis >= beforeThis && afterThis - beforeThis <= amt)
        );
    }

    receive() external payable {}
}

