// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Wallet c;

    function setUp() public {
        c = new Wallet();
    }

    function _run(uint256 amt) internal {
        vm.deal(address(c), VALUE_CAP);
        uint256 beforeC = address(c).balance;
        uint256 beforeThis = address(this).balance;
        bool reverted;
        try c.withdraw(amt) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterC = address(c).balance;
        uint256 afterThis = address(this).balance;
        assertTrue((reverted && afterC == beforeC && afterThis == beforeThis)
            || (!reverted && afterC + amt == beforeC && afterThis >= beforeThis && afterThis - beforeThis <= amt));
    }

    function testFuzz_run(uint256 amt) public {
        _run(amt);
    }

    receive() external payable {}
}
